{"source":"#include<stdio.h>
int main(int argc, char *argv[])
{
 int n,c,x[1000],i,max;
 scanf("%d%d",&n,&c);
 for(i=0;i<n;i++)
 scanf("%d",&x[i]);
 max=x[0]-x[1]-c;
 for(i=0;i<n-1;i++)
 if(max<(x[i]-x[i+1]-c))
 max=x[i]-x[i+1]-c;
 if(max>0)
 printf("%d\n",max);
 else
 printf("0\n");
 return 0;
}"}
